{
  "explanation": "The inscribed angle theorem says that an angle whose vertex P lies on a circle and whose sides pass through two fixed points A and B (intercepting arc AB) measures exactly half the central angle ∠AOB that subtends the same arc. So as you drag P along an arc, ∠APB stays constant — and if you cross to the other arc between A and B, it jumps to a different constant (half of the reflex arc).",
  "manimCode": "const cx = 0;
const cy = 0.25;
const R = 2.65;
const centerPt = [cx, cy, 0];

const circle = new Circle({ radius: R, color: WHITE });
circle.moveTo(centerPt);
circle.setStrokeWidth(2);

const oDot = new Dot({ point: centerPt, color: GRAY });

function fromAngle(th) {
  return [cx + R * Math.cos(th), cy + R * Math.sin(th), 0];
}

function toCircle(pos) {
  const dx = pos[0] - cx;
  const dy = pos[1] - cy;
  const len = Math.sqrt(dx * dx + dy * dy) || 1;
  return [cx + (R * dx) / len, cy + (R * dy) / len, 0];
}

const thA0 = 130 * Math.PI / 180;
const thB0 = 50 * Math.PI / 180;
const thP0 = 250 * Math.PI / 180;

const dotA = new Dot({ point: fromAngle(thA0), color: RED });
const dotB = new Dot({ point: fromAngle(thB0), color: RED });
const dotP = new Dot({ point: fromAngle(thP0), color: YELLOW });

const chordAB = new Polygon({ vertices: [fromAngle(thA0), fromAngle(thB0)], color: ORANGE });
chordAB.setStrokeWidth(2.5).setFillOpacity(0);

const linePA = new Polygon({ vertices: [fromAngle(thP0), fromAngle(thA0)], color: BLUE });
linePA.setStrokeWidth(3).setFillOpacity(0);

const linePB = new Polygon({ vertices: [fromAngle(thP0), fromAngle(thB0)], color: BLUE });
linePB.setStrokeWidth(3).setFillOpacity(0);

const lineOA = new Polygon({ vertices: [centerPt, fromAngle(thA0)], color: GREEN });
lineOA.setStrokeWidth(2).setFillOpacity(0);

const lineOB = new Polygon({ vertices: [centerPt, fromAngle(thB0)], color: GREEN });
lineOB.setStrokeWidth(2).setFillOpacity(0);

const arcInscribed = new Polygon({ vertices: [fromAngle(thP0), fromAngle(thP0)], color: YELLOW });
arcInscribed.setStrokeWidth(3).setFillOpacity(0);

const arcCentral = new Polygon({ vertices: [centerPt, centerPt], color: GREEN });
arcCentral.setStrokeWidth(3).setFillOpacity(0);

const arcAB = new Polygon({ vertices: [fromAngle(thA0), fromAngle(thB0)], color: ORANGE });
arcAB.setStrokeWidth(5).setFillOpacity(0).setOpacity(0.7);

function angleBetween(a, b) {
  let d = b - a;
  while (d <= -Math.PI) d += 2 * Math.PI;
  while (d > Math.PI) d -= 2 * Math.PI;
  return d;
}

function buildArc(vertex, p1, p2, arcR, n) {
  const a1 = Math.atan2(p1[1] - vertex[1], p1[0] - vertex[0]);
  const a2 = Math.atan2(p2[1] - vertex[1], p2[0] - vertex[0]);
  const d = angleBetween(a1, a2);
  const verts = [];
  const steps = n || 18;
  for (let i = 0; i <= steps; i++) {
    const t = a1 + (d * i) / steps;
    verts.push([
      vertex[0] + arcR * Math.cos(t),
      vertex[1] + arcR * Math.sin(t),
      0
    ]);
  }
  return verts;
}

function buildCircleArc(th1, th2, rad, n) {
  let d = th2 - th1;
  while (d <= -Math.PI) d += 2 * Math.PI;
  while (d > Math.PI) d -= 2 * Math.PI;
  const verts = [];
  const steps = n || 24;
  for (let i = 0; i <= steps; i++) {
    const t = th1 + (d * i) / steps;
    verts.push([cx + rad * Math.cos(t), cy + rad * Math.sin(t), 0]);
  }
  return verts;
}

function vecAngle(px, py, ax, ay, bx, by) {
  const v1x = ax - px;
  const v1y = ay - py;
  const v2x = bx - px;
  const v2y = by - py;
  const dot = v1x * v2x + v1y * v2y;
  const cr = v1x * v2y - v1y * v2x;
  return Math.abs(Math.atan2(cr, dot));
}

function pointAngle(pt) {
  return Math.atan2(pt[1] - cy, pt[0] - cx);
}

const title = new Text({ text: 'Inscribed Angle Theorem', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.45, 0]);

const subtitle = new Text({
  text: 'Drag P — ∠APB stays constant on the same arc',
  color: GRAY,
  fontSize: 20
});
subtitle.moveTo([0, 2.95, 0]);

const formula = new MathTex({ latex: '\\angle APB = \\tfrac{1}{2}\\angle AOB' });
await formula.waitForRender();
formula.moveTo([0, -3.35, 0]);

let readOut = new Text({ text: '∠APB = —    ∠AOB = —', color: WHITE, fontSize: 24 });
readOut.moveTo([0, -2.7, 0]);

const txtA = new Text({ text: 'A', color: RED, fontSize: 26 });
const txtB = new Text({ text: 'B', color: RED, fontSize: 26 });
const txtP = new Text({ text: 'P', color: YELLOW, fontSize: 26 });
const txtO = new Text({ text: 'O', color: GRAY, fontSize: 22 });
txtO.moveTo([cx - 0.32, cy - 0.32, 0]);

function placeOutside(lbl, pt) {
  const dx = pt[0] - cx;
  const dy = pt[1] - cy;
  const len = Math.sqrt(dx * dx + dy * dy) || 1;
  const off = 0.4;
  lbl.moveTo([pt[0] + (off * dx) / len, pt[1] + (off * dy) / len, 0]);
}

function updateReadOut(insDeg, cenDeg) {
  const pos = readOut.getCenter();
  scene.remove(readOut);
  const half = cenDeg / 2;
  const match = Math.abs(insDeg - half) < 1.2 || Math.abs(insDeg - (180 - half)) < 1.2;
  readOut = new Text({
    text: '∠APB = ' + insDeg.toFixed(1) + '°     ∠AOB = ' + cenDeg.toFixed(1) + '°     ½∠AOB = ' + half.toFixed(1) + '°',
    color: match ? GREEN_A : WHITE,
    fontSize: 22
  });
  readOut.moveTo(pos);
  scene.add(readOut);
}

function refresh() {
  const pA = dotA.getCenter();
  const pB = dotB.getCenter();
  const pP = dotP.getCenter();

  linePA.setVertices([pP, pA]);
  linePB.setVertices([pP, pB]);
  chordAB.setVertices([pA, pB]);
  lineOA.setVertices([centerPt, pA]);
  lineOB.setVertices([centerPt, pB]);

  arcInscribed.setVertices(buildArc(pP, pA, pB, 0.5, 20));
  arcCentral.setVertices(buildArc(centerPt, pA, pB, 0.6, 20));

  const th1 = pointAngle(pA);
  const th2 = pointAngle(pB);
  arcAB.setVertices(buildCircleArc(th1, th2, R, 28));

  placeOutside(txtA, pA);
  placeOutside(txtB, pB);
  placeOutside(txtP, pP);

  const ins = vecAngle(pP[0], pP[1], pA[0], pA[1], pB[0], pB[1]);
  const cen = vecAngle(cx, cy, pA[0], pA[1], pB[0], pB[1]);
  updateReadOut((ins * 180) / Math.PI, (cen * 180) / Math.PI);
}

scene.add(
  circle,
  arcAB,
  oDot,
  lineOA,
  lineOB,
  chordAB,
  linePA,
  linePB,
  arcCentral,
  arcInscribed,
  dotA,
  dotB,
  dotP,
  txtA,
  txtB,
  txtP,
  txtO,
  title,
  subtitle,
  formula,
  readOut
);

function bindDrag(dot) {
  makeDraggable(dot, scene, {
    onDrag: (mob, pos) => {
      mob.moveTo(toCircle(pos));
      refresh();
    }
  });
  makeHoverable(dot, scene, { hoverScale: 1.35, hoverColor: WHITE });
}

bindDrag(dotA);
bindDrag(dotB);
bindDrag(dotP);

const controls = new Controls(scene, { position: 'bottom-right', width: 150 });
controls.addButton({
  label: 'Reset',
  onClick: () => {
    dotA.moveTo(fromAngle(thA0));
    dotB.moveTo(fromAngle(thB0));
    dotP.moveTo(fromAngle(thP0));
    refresh();
  }
});

refresh();
await scene.wait(999999);"
